-- Copyright-safe, original questions covering topics observed in @PedMahoratGuli.
-- Channel is a topic-discovery pointer, NOT licensed source text or verified prior-exam key.
-- The content below was independently authored and verified against M14-M16 source-backed lessons.
-- Stage only in GitHub feature branch. Apply to production only upon explicit user approval.
-- 30 new Y1 items: KS 8, PM.GEN 18, PM.MET 4.
begin;
do $pedguli$
declare
  r record;
  v_subject uuid;
  v_construct uuid;
  v_lesson uuid;
  v_qid uuid;
  v_oid uuid;
  i int;
begin
  select id into strict v_subject from public.subjects where code='informatika';
  for r in select * from jsonb_to_recordset($items$[{"n":101,"construct":"KS.01","stem":"Muammoli vazifalarni bajarishga mo‘ljallangan dars rejasida natija qanday yozilsa baholashga qulay bo‘ladi?","options":["O‘quvchi algoritmda uch turdagi xatoni aniqlab tuzata oladi","Dars yaxshi o‘tadi","O‘quvchilar ko‘p narsani bilib oladi","Slaydlar chiroyli bo‘ladi"],"answer":0,"explanation":"Natija kuzatiladigan va o‘lchanadigan harakat bilan ifodalanadi.","cognitive":"qollash","difficulty":3},{"n":102,"construct":"KS.02","stem":"Loyiha asosida o‘qitishda o‘qituvchi faqat yakuniy mahsulotga baho qo‘ysa, qanday muhim dalil yetishmaydi?","options":["Partalar tozaligi","Hamkorlik, izlanish va bosqichma-bosqich rivojlanish jarayoni","Dars boshlangan soat","Taqdimot fonining rangi"],"answer":1,"explanation":"Loyiha usulida jarayon va yakuniy natijani birga baholash muhim.","cognitive":"mulohaza","difficulty":4},{"n":103,"construct":"KS.03","stem":"Ikki o‘quvchi bir xil xatoga yo‘l qo‘ydi, ammo sabablari har xil. Qayta aloqa qanday beriladi?","options":["Ikkalasiga tayyor bir xil tanbeh beriladi","Faqat ball aytiladi","Xatoning sababiga qarab mos, amalga oshiriladigan tavsiya beriladi","Baholashdan voz kechiladi"],"answer":2,"explanation":"Qayta aloqa diagnostika natijasiga va o‘quvchining ehtiyojiga bog‘lanadi.","cognitive":"qollash","difficulty":3},{"n":104,"construct":"KS.04","stem":"Guruh taqdimotida sustroq ishtirokchi fikrini ayta olmayapti. O‘qituvchining tarbiyaviy vazifasiga eng mos yo‘l qaysi?","options":["Faqat tez gapiruvchilarga navbat berish","Uni sinf oldida uyaltirish","Barcha javobni o‘qituvchi aytib qo‘yish","Hurmatli muloqot qoidalarini mustahkamlab, har biriga navbat ajratish"],"answer":3,"explanation":"Tarbiyaviy ishda o‘zaro hurmat va teng ishtirokni ta’minlash zarur.","cognitive":"qollash","difficulty":3},{"n":105,"construct":"KS.05","stem":"O‘quvchi shaxsiy ma’lumotini boshqa o‘quvchilar tarqatganini aytdi. Qaysi birinchi choralar xavfsiz?","options":["Ma’lumotni yana bir marta guruhga ulashish","Tarqatishni to‘xtatish, zarar ko‘rgan o‘quvchini himoya qilish va vakolatli shaxsga xabar berish","Shikoyatni inkor qilish","Faqat sinfga umumiy past baho qo‘yish"],"answer":1,"explanation":"Xavfsiz muhitda kiberbullingdan himoya va maxfiylik muhim.","cognitive":"mulohaza","difficulty":4},{"n":106,"construct":"KS.05","stem":"Inklyuziv informatika darsida ekranni o‘qish qiyin bo‘lgan o‘quvchi mavjud. Qanday asoslash yaxshiroq?","options":["Barcha raqamli mashg‘ulotlarni bekor qilish","Bu o‘quvchi alohida maqsadsiz topshiriq olishi kerak","Bir xil o‘quv maqsadini saqlab, material formatini moslashtirish","Faqat doskada juda kichik shrift ishlatish"],"answer":2,"explanation":"Maqsadni saqlagan holda foydalanish imkoniyatini ta’minlash inklyuzivlikka mos.","cognitive":"qollash","difficulty":3},{"n":107,"construct":"KS.06","stem":"O‘qituvchi yangi interfaol metodni qo‘llagach, kutilgan natija bo‘lmadi. Kasbiy refleksiyaning ishonchli belgisi qaysi?","options":["Natijalarni va o‘quvchi fikrini tahlil qilib metodni qayta sozlash","Faqat metod nomini o‘zgartirish","O‘quvchilarni asossiz ayblash","Birinchi muvaffaqiyatsizlikdan so‘ng barcha metodni rad etish"],"answer":0,"explanation":"Kasbiy rivojlanish dalilga tayangan o‘zgarishni nazarda tutadi.","cognitive":"mulohaza","difficulty":4},{"n":108,"construct":"KS.07","stem":"O‘quvchining mustaqil loyihasi bo‘yicha ota-ona va ikki fan o‘qituvchisi hamkorlik qilmoqda. Kelishuvdagi asosiy shart?","options":["Baholashdan birini yashirish","O‘quvchi fikrini hisobga olmaslik","Barcha shaxsiy ma’lumotlarni ommaga tarqatish","Umumiy maqsad, mas’uliyat va zarur ma’lumotning maxfiy chegarasini kelishish"],"answer":3,"explanation":"Hamkorlik rejalash, vazifalarni aniq ajratish va maxfiylikni talab etadi.","cognitive":"qollash","difficulty":3},{"n":109,"construct":"PM.GEN.01","stem":"Bilimni tayyor holda berish o‘rniga o‘quvchiga qarama-qarshi dalillar asosida yechim izlatilsa, bu nimaga misol?","options":["Faqat takrorlash","Muammoli ta’lim","Faqat summativ nazorat","Faqat ko‘rgazmali namoyish"],"answer":1,"explanation":"Muammoli ta’lim bilish ziddiyatidan yechim izlashga undaydi.","cognitive":"qollash","difficulty":3},{"n":110,"construct":"PM.GEN.01","stem":"O‘quvchining yosh xususiyati yangi tushunchaning taqdim etilishiga qanday ta’sir qiladi?","options":["Faqat baholash sanasini o‘zgartiradi","Hech qanday ta’sir qilmaydi","Misol, ko‘rgazma va murakkablik darajasini tanlashga ta’sir qiladi","Faqat partalar sonini belgilaydi"],"answer":2,"explanation":"Didaktik tanlov yosh va bilish imkoniyatiga mos bo‘lishi kerak.","cognitive":"bilish","difficulty":2},{"n":111,"construct":"PM.GEN.02","stem":"Nazariya va amaliyot birligi tamoyilini qaysi vazifa yaxshiroq ifodalaydi?","options":["Yangi tushunchani kundalik vaziyatda qo‘llab ko‘rib, natijani tahlil qilish","Faqat atama ta’rifini besh marta ko‘chirish","Faqat murakkab termin aytish","Darsni faqat yakuniy test bilan boshlash"],"answer":0,"explanation":"Tushuncha real faoliyatda sinalganda nazariya-amaliyot bog‘lanadi.","cognitive":"qollash","difficulty":3},{"n":112,"construct":"PM.GEN.02","stem":"O‘quvchilar yangi natijaga o‘zlari tajriba qilib kelishdi, o‘qituvchi xulosani dalillar bilan tekshirdi. Qaysi didaktik tamoyil ustun?","options":["Tasodifiylik","Passiv eshitish","Faqat jazolash","Onglilik va faollik"],"answer":3,"explanation":"O‘quvchi faol bilish jarayonida mustaqil xulosa chiqaradi.","cognitive":"qollash","difficulty":3},{"n":113,"construct":"PM.GEN.03","stem":"Maktab miqyosida sinfni obodonlashtirish loyihasida o‘quvchilar mehnatni taqsimladi. Tarbiyaviy natijani qaysi belgi ko‘rsatadi?","options":["Vazifadan qochish","Faqat yakuniy surat olish","Mas’uliyat bilan ishni tugatish va boshqalarning mehnatini qadrlash","Tayyor materialni topshirmay yashirish"],"answer":2,"explanation":"Mehnat tarbiyasi mas’uliyat va mehnatga munosabatni rivojlantiradi.","cognitive":"mulohaza","difficulty":4},{"n":114,"construct":"PM.GEN.04","stem":"O‘quvchilar ichki doirada savolni muhokama qiladi, tashqi doira jarayonni kuzatib baholaydi; keyin rollar almashadi. Usulning nomi?","options":["Ajurli arra","Akvarium","Keys-stadi","Debatning yozma shakli"],"answer":1,"explanation":"Akvarium metodida ichki ishtirokchilar fikr almashadi, tashqi doira kuzatadi.","cognitive":"qollash","difficulty":3},{"n":115,"construct":"PM.GEN.04","stem":"Asalari galasi usuli bilan o‘quvchilar kichik guruhlarda tezkor fikr almashmoqda. Shu usulning eng xarakterli belgisi qaysi?","options":["Uzoq muddatli individual ilmiy hisobot","Faqat o‘qituvchining yakuniy ma’ruzasi","Bitta o‘quvchining 40 daqiqalik monologi","Qisqa va faol guruh muhokamasi, g‘oyalarni tez almashish"],"answer":3,"explanation":"Tezkor kichik guruh muhokamasi shu interfaol usulning ajratuvchi belgisidir.","cognitive":"qollash","difficulty":3},{"n":116,"construct":"PM.GEN.05","stem":"Sinf rahbari ota-onaga o‘quvchining rivojlanishi haqida ma’lumot bermoqda. Qaysi ma’lumotni berishdan tiyilishi kerak?","options":["Boshqa bolaning shaxsiy qiyinchiligi va bahosi","Farzandining o‘z rivojlanishi","Keyingi hamkorlik rejasi","Mashg‘ulot vaqti"],"answer":0,"explanation":"Boshqa o‘quvchiga oid maxfiy ma’lumotni oshkor etish mumkin emas.","cognitive":"qollash","difficulty":3},{"n":117,"construct":"PM.GEN.06","stem":"O‘qituvchi noto‘g‘ri javobni muhokama qilishdan avval bolani ruhiy jihatdan qo‘lladi. Qaysi xususiyat asosiy?","options":["Bilimlarni e’tiborsiz qoldirish","Javobni yashirish","Pedagogik takt","Jazolash intizomi"],"answer":2,"explanation":"Pedagogik takt bolaning qadr-qimmatini saqlab, vaziyatga mos muomalani talab etadi.","cognitive":"qollash","difficulty":3},{"n":118,"construct":"PM.GEN.06","stem":"O‘qituvchi murakkab vaziyatda ohangini, yuz ifodasini va nutq sur’atini boshqardi. Bu qaysi ko‘nikmaga ko‘proq kiradi?","options":["Faqat didaktik prinsip","Pedagogik texnika","Faqat baholash mezoni","Tashqi motivatsiyani bekor qilish"],"answer":1,"explanation":"Pedagogik texnika muloqotning ifodaviy va o‘zini boshqarish jihatlarini qamraydi.","cognitive":"bilish","difficulty":2},{"n":119,"construct":"PM.GEN.07","stem":"O‘qituvchi darsni oldindan tasavvur qilib, o‘quvchilarning savollari va qiyinchiliklarini taxmin qiladi. Bu qaysi qobiliyatga yaqin?","options":["Kompyuterga xizmat ko‘rsatish","Faqat nazorat qilish","Faqat yozuv malakasi","Pedagogik xayol va oldindan ko‘ra olish"],"answer":3,"explanation":"Pedagogik xayol kutilayotgan vaziyatlarni oldindan model qilishga yordam beradi.","cognitive":"qollash","difficulty":3},{"n":120,"construct":"PM.GEN.07","stem":"O‘quvchi berilgan vazifadan xavotirlanayotganini sezib, muallim yondashuvini moslashtirdi. Qaysi qobiliyat yetakchi?","options":["Perseptiv qobiliyat","Faqat tashkilot hujjatlarini yuritish","Faqat jismoniy epchillik","Faqat yozma diktant olish"],"answer":0,"explanation":"Perseptiv qobiliyat o‘quvchining ichki holatini idrok etishga xizmat qiladi.","cognitive":"qollash","difficulty":3},{"n":121,"construct":"PM.GEN.08","stem":"Ajurli arra (jigsaw) metodida mutaxassislar guruhi nima qiladi?","options":["Barcha o‘quvchi bir xil mavzuni yakka yodlaydi","Bir o‘quvchi qolganlarni imtihon qiladi","Bir qism materialni chuqur o‘rganib, asosiy guruhga qaytib boshqalarga tushuntiradi","Tashqi doira ichki doirani faqat kuzatadi"],"answer":2,"explanation":"Jigsaw usuli qismlar bo‘yicha ekspertlik va o‘zaro o‘qitishga tayanadi.","cognitive":"bilish","difficulty":2},{"n":122,"construct":"PM.GEN.08","stem":"O‘quvchi muammoni o‘rganib, ma’lumot yig‘ib, yakuniy mahsulot yaratadi va asoslaydi. Ushbu yondashuv qaysi?","options":["Faqat og‘zaki nazorat","Loyiha asosida o‘qitish","Faqat ma’ruza","Akvarium metodining kuzatish bosqichi"],"answer":1,"explanation":"Loyiha usulida natija real mahsulot yoki yechim hamda uning asosidan iborat.","cognitive":"qollash","difficulty":3},{"n":123,"construct":"PM.GEN.08","stem":"Guruhlarning bir qismi mavzuni tez o‘zlashtirmoqda, boshqalari ko‘makka muhtoj. Individual ta’limning mos amaliy belgisi?","options":["Hamma uchun doim bir xil tezlik","Faqat sust o‘quvchilarni darsdan chiqarish","Ko‘nikmaga bog‘liq topshiriqlarni umuman bermaslik","O‘quvchining sur’ati va ehtiyojiga ko‘ra topshiriq hamda ko‘makni moslash"],"answer":3,"explanation":"Individual yondashuv sur’at, qiyinchilik va yordamni moslashtiradi.","cognitive":"qollash","difficulty":3},{"n":124,"construct":"PM.GEN.08","stem":"O‘qituvchi o‘quvchilarni real vaziyat va dalillarni tahlil qilib, variantlarni muhokama qilishga undadi. Metod nomi qaysi?","options":["Keys-stadi","Faqat yodlash","Faqat diktant","Faqat o‘qituvchi ma’ruzasi"],"answer":0,"explanation":"Keys-stadi muayyan holatni tahlil qilish va qarorlarni asoslashni talab etadi.","cognitive":"qollash","difficulty":3},{"n":125,"construct":"PM.GEN.08","stem":"Vazifada bir nechta to‘g‘ri yechim bo‘lishi mumkin. Muammoni cheklovlari bilan birga taqdim etish nima uchun muhim?","options":["Yagona javobni majburan berish uchun","O‘quvchilarning mustaqil yechimini butunlay to‘xtatish uchun","Tanlovni dalil bilan asoslash va ijodiy fikrlashni faollashtirish uchun","Faqat baholash vaqtini uzaytirish uchun"],"answer":2,"explanation":"Muammoli vaziyat izlanish va asoslangan yechim tanlashga xizmat qiladi.","cognitive":"mulohaza","difficulty":4},{"n":126,"construct":"PM.GEN.08","stem":"Metodning afzalliklarini moslashtirishda loyiha ta’limi nimani ko‘proq rivojlantiradi?","options":["Faqat tez yodlashni","Hamkorlik, rejalash va yakuniy natija uchun mas’uliyatni","Faqat bir javobni nusxalashni","Faqat tinglab turishni"],"answer":1,"explanation":"Loyiha ishida hamkorlik hamda rejadan mahsulotgacha bo‘lgan faoliyat muhim.","cognitive":"qollash","difficulty":3},{"n":127,"construct":"PM.MET.01","stem":"Informatikada blok-sxema va dastur natijasi bir-biriga mos kelmadi. Qaysi o‘quv faoliyati maqsadga mos?","options":["Xatoni tekshirmasdan ishni tugatish","Faqat diagramma rangini o‘zgartirish","Dasturdan voz kechish","Algoritm qadamlarini izma-iz tekshirib, moslikni dalil bilan aniqlash"],"answer":3,"explanation":"Tuzilmaviy kuzatuv algoritmik fikrlashni rivojlantiradi.","cognitive":"mulohaza","difficulty":4},{"n":128,"construct":"PM.MET.01","stem":"Algoritmni turli usulda tasvirlash mavzusida maqsad nimaga qaratilishi kerak?","options":["Bitta masalani matn, blok-sxema va kod shaklida ifodalab, ularning mosligini tekshirish","Faqat tayyor kodni nusxalash","Chizmalarning faqat bezagini tanlash","Amaliyotni umuman rad etish"],"answer":0,"explanation":"Bir masalaning bir nechta formal tasvirini bog‘lash metodik maqsadga mos.","cognitive":"qollash","difficulty":3},{"n":129,"construct":"PM.MET.02","stem":"Informatika darsida ‘jigsaw’ asosida tarmoq topologiyalari o‘rganilmoqda. Qaysi bosqich zarur?","options":["Hamma guruhga faqat bir mavzuni berib, muloqotni taqiqlash","Har guruh faqat o‘qituvchini tinglaydi","Ekspert guruhlar o‘z qismini o‘rganib, qaytganida boshqa guruhdoshlariga tushuntiradi","Faqat yakuniy baholarni e’lon qilish"],"answer":2,"explanation":"Jigsaw materialni qismlarga ajratib o‘zaro o‘qitishga tayanadi.","cognitive":"qollash","difficulty":3},{"n":130,"construct":"PM.MET.03","stem":"O‘quvchi dasturidagi xatoni o‘qituvchi o‘zi tuzatib qo‘ya qolmoqda. Bu nimani cheklaydi?","options":["Faqat sinf vaqtini","O‘quvchining diagnostika, gipoteza va mustaqil debugging ko‘nikmasini","Kompyuter xotirasini","Fayl hajmini"],"answer":1,"explanation":"To‘liq tayyor yechim berish o‘quvchining mustaqil xato tuzatish tajribasini kamaytiradi.","cognitive":"mulohaza","difficulty":4}]$items$::jsonb)
  as t(n int, construct text, stem text, options jsonb, answer int, explanation text, cognitive text, difficulty int)
  loop
    select c.id, l.id into v_construct,v_lesson from public.constructs c
    join public.lesson_constructs lc on lc.construct_id=c.id
    join public.lessons l on l.id=lc.lesson_id
    where c.code=r.construct and c.is_active and l.status='published'::public.content_status
    and l.slug !~ '^m(14|15|16)-[0-9]+$'
    order by l.id limit 1;
    if v_construct is null or v_lesson is null then raise exception 'pedguli_missing_source_lesson: %',r.construct; end if;
    v_qid:=('79000000-0000-4000-8000-'||lpad(r.n::text,12,'0'))::uuid;
    insert into public.questions (id,subject_id,construct_id,group_code,format,cognitive,difficulty,stem_md,status,source_reference,source_lesson_id)
    values (v_qid,v_subject,v_construct,
      case when r.construct like 'KS.%' then 'KS' when r.construct like 'PM.GEN.%' then 'PM.GEN' else 'PM.MET' end,
      'Y1'::public.question_format,r.cognitive::public.cognitive_level,r.difficulty,r.stem,
      'published'::public.content_status,
      'authored:pedguli-topic-study:v2:'||r.construct||':'||r.n,v_lesson)
    on conflict (id) do nothing;
    for i in 0..3 loop
      v_oid:=('79100000-0000-4000-8000-'||lpad((r.n*10+i)::text,12,'0'))::uuid;
      insert into public.question_options(id,question_id,side,order_idx,content_md)
      values(v_oid,v_qid,'a',i+1,r.options->>i) on conflict(id) do nothing;
    end loop;
    v_oid:=('79100000-0000-4000-8000-'||lpad((r.n*10+r.answer)::text,12,'0'))::uuid;
    insert into public.question_keys(question_id,payload,explanation_md)
    values(v_qid,jsonb_build_object('correct_option_id',v_oid),r.explanation)
    on conflict(question_id) do nothing;
  end loop;
end
$pedguli$;
commit;
